public int LongestCommonSubsequence(string a, string b) {
    var dp = new int[a.Length + 1, b.Length + 1];   // row 0 and column 0 are zeros
    for (int i = 1; i <= a.Length; i++)
        for (int j = 1; j <= b.Length; j++)
            dp[i, j] = a[i - 1] == b[j - 1]
                ? dp[i - 1, j - 1] + 1                    // a pair: diagonal + 1
                : Math.Max(dp[i - 1, j], dp[i, j - 1]);   // cut one character
    return dp[a.Length, b.Length];
}

